const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const envPath = path.join(__dirname, '..', '.env.production');

if (fs.existsSync(envPath)) {
  console.log('⚠️  .env.production already exists. Skipping generation to prevent overwrite.');
  process.exit(0);
}

const generateSecret = (length = 32) => crypto.randomBytes(length).toString('hex');

const secrets = [
  '# Production Environment Variables',
  '# Generated by scripts/generate-prod-secrets.js',
  '',
  '# Server Configuration',
  'NODE_ENV=production',
  'PORT=4001',
  'STORAGE_MODE=local',
  '',
  '# Security Secrets (DO NOT SHARE)',
  `JWT_SECRET=${generateSecret()}`,
  `NEXTAUTH_SECRET=${generateSecret()}`,
  '',
  '# Database (Neo4j - Optional)',
  '# NEO4J_URI=bolt://neo4j:7687',
  '# NEO4J_USER=neo4j',
  `# NEO4J_PASSWORD=${generateSecret()}`,
  '',
  '# Storage',
  'MAX_FILE_SIZE_MB=50',
  '',
  '# Web Configuration',
  'NEXT_PUBLIC_API_URL=http://localhost:4001',
  '# INTERNAL_API_URL=http://api:4001 # Used for SSR in Docker',
  'NEXT_PUBLIC_STORAGE_MODE=local',
  '',
].join('\n');

fs.writeFileSync(envPath, secrets);

console.log('✅ .env.production created with secure secrets.');
console.log(
  '👉 Review the file and fill in any missing external service keys (e.g., OpenAI, Google OAuth).'
);
